# Now I understand the pattern. Let me create the transform function
# and test it against both demo and then apply to test input

import json

def transform_cell_block(grid):
    """Transform a cell block grid where:
    - 2s expand horizontally (fill their row block's columns)
    - 3s expand vertically (fill their col block's rows)
    - 6s appear at intersections of 2-expansion rows and 3-expansion cols

    The abstract grid has n + 1 blocks in each direction (dividers at indices 0..n-1)
    """
    h, w = len(grid), len(grid[0])

    # Find dividers
    div_r = sorted([r for r in range(h) if all(grid[r][c] == 8 for c in range(w))])
    div_c = sorted([c for c in range(w) if all(grid[r][c] == 8 for r in range(h))])

    # Number of abstract blocks
    # div_r at [d0, d1, d2] creates 4 blocks: [0,d0), [d0,d1), [d1,d2), [d2,h)
    # So n_blocks = len(div) + 1
    n_blocks_r = len(div_r) + 1
    n_blocks_c = len(div_c) + 1

    # Build output
    output = [[0] * w for _ in range(h)]

    # Map abstract (br, bc) to grid ranges
    def br_to_grid_br(br):
        if br == 0:
            return (0, div_r[0])
        elif br < n_blocks_r - 1:
            return (div_r[br - 1], div_r[br])
        else:
            return (div_r[br - 1], h)

    def bc_to_grid(bc):  
        if bc == 0:
            return (0, div_c[0])
        elif bc < n_blocks_c - 1:
            return (div_c[bc - 1], div_c[bc])
        else:
            return (div_c[bc - 1], w)

    # Parse abstract grid
    abs_grid = {}
    for br in range(n_blocks_r):
        for bc in range(n_blocks_c):
            br_start, br_end = br_to_grid_br(br)
            bc_start, bc_end = bc_to_grid(bc)
            # Center of this block
            center_r = (br_start + br_end) // 2
            center_c = (bc_start + bc_end) // 2
            if 0 <= center_r < h:
                center_r = grid[center_r][center_c] if 0 <= center_c < w else grid[0][0]
                if center_r not in [0, 8]:
                    abs_grid[(br, bc)] = center_r

    # Find which rows/cols have 2 or 3
    rows_2 = {br for (br, bc), v in abs_grid.items() if v == 2}
    rows_3 = {br for (br, bc), v in abs_grid.items() if v == 3}
    cols_2 = {bc for (br, bc), v in abs_grid.items() if v == 2}
    cols_3 = {bc for (br, bc), v in abs_grid.items() if v == 3}

    # Expand 2s horizontally in their rows
    for br in rows_2:
        br_start, br_end = br_to_grid_br(br)
        for r in range(br_start, br_end):
            bc_start, bc_end = 0, w
            for bc in range(n_blocks_c):
                bc_s, bc_e = bc_to_grid(bc)
                for c in range(bc_s, bc_e):
                    output[r][c] = 2

    # Expand 3s vertically in their cols
    for bc in cols_3:
        bc_start, bc_end = bc_to_grid(bc)
        for c in range(bc_start, bc_end):
            br_start, br_end = 0, h
            for br in range(n_blocks_r):
                br_s, br_e = br_to_grid_br(br)
                for r in range(br_s, br_e):
                    output[r][c] = 3

    # Create 6s at intersections (where a 2-row and 3-col cross)
    for br in rows_2:
        br_start, br_end = br_to_grid_br(br)
        for r in range(br_start, br_end):
            for bc in cols_3:
                bc_start, bc_end = bc_to_grid(bc)
                for c in range(bc_start, bc_end):
                    output[r][c] = 6

    # Remove 6 from if a 2 or 3 should take precedence (based on demo)
    # Actually, looking at demo, 6s fill the intersection areas
    # But 2s and 3s don't override 6s in intersections

    return output

